import{_ as e,C as a,c as o,o as i,j as l,b as n,a0 as r,a as s,w as t,G as u,a1 as d}from"./chunks/framework.DKRgXLPU.js";const c=JSON.parse('{"title":"Ser un gran jugador de equipo","description":"","frontmatter":{},"headers":[],"relativePath":"es/education/team-player/index.md","filePath":"es/education/team-player/index.md"}');const p=e({name:"es/education/team-player/index.md"},[["render",function(e,c,p,m,h,q){const b=a("Mermaid");return i(),o("div",null,[c[1]||(c[1]=l("h1",{id:"ser-un-gran-jugador-de-equipo",tabindex:"-1"},[s("Ser un gran jugador de equipo "),l("a",{class:"header-anchor",href:"#ser-un-gran-jugador-de-equipo","aria-label":'Permalink to "Ser un gran jugador de equipo"'},"​")],-1)),c[2]||(c[2]=l("p",null,"La petanca se juega a menudo en equipos: dobles (dobles) o triples (tripletes). La habilidad individual importa, pero la dinámica del equipo puede determinar el resultado. Los mejores equipos no siempre son los más hábiles, sino los que mejor trabajan juntos.",-1)),c[3]||(c[3]=l("div",{class:"tip custom-block"},[l("p",{class:"custom-block-title"},"La gran idea"),l("p",null,[l("strong",null,"Los mejores equipos no siempre son los más hábiles: son los que trabajan mejor juntos."),s(" Ser humilde, tener hambre y ser emocionalmente inteligente te convierte en un gran compañero de equipo.")])],-1)),(i(),n(d,null,{default:t(()=>[u(b,{id:"mermaid-11",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BGran%20compa%C3%B1ero%20de%20equipo%5D%20--%3E%20B%5BHumilde%5D%0A%20%20%20%20A%20--%3E%20C%5BHambriento%5D%0A%20%20%20%20A%20--%3E%20D%5BElegante%5D%0A%0A%20%20%20%20B%20--%3E%20E%5B%C3%89xito%20del%20equipo%5D%0A%20%20%20%20C%20--%3E%20E%0A%20%20%20%20D%20--%3E%20E%0A%0A%20%20%20%20E%20--%3E%20F%5BRendimiento%20en%20el%20campeonato%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20B%20fill%3A%23e3f2fd%0A%20%20%20%20style%20C%20fill%3A%23fff4e1%0A%20%20%20%20style%20D%20fill%3A%23f3e5f5%0A%20%20%20%20style%20F%20fill%3A%23fff4e1%0A"})]),fallback:t(()=>[...c[0]||(c[0]=[s(" Loading... ",-1)])]),_:1})),c[4]||(c[4]=r('<h2 id="¿que-hace-a-un-gran-companero-de-equipo" tabindex="-1">¿Qué hace a un gran compañero de equipo? <a class="header-anchor" href="#¿que-hace-a-un-gran-companero-de-equipo" aria-label="Permalink to &quot;¿Qué hace a un gran compañero de equipo?&quot;">​</a></h2><p>La investigación y la experiencia apuntan a tres cualidades clave:</p><h3 id="_1-humilde" tabindex="-1">1. Humilde <a class="header-anchor" href="#_1-humilde" aria-label="Permalink to &quot;1. Humilde&quot;">​</a></h3><ul><li>Prioriza el éxito del equipo sobre la gloria personal</li><li>Reconoce las contribuciones de los demás</li><li>Admite errores sin excusas</li><li>Abierto a la retroalimentación y al aprendizaje.</li><li>No necesita ser la estrella</li></ul><h3 id="_2-hambriento" tabindex="-1">2. Hambriento <a class="header-anchor" href="#_2-hambriento" aria-label="Permalink to &quot;2. Hambriento&quot;">​</a></h3><ul><li>Automotivado y motivado</li><li>Hace el trabajo sin que se lo pidan</li><li>Siempre buscando mejorar</li><li>Aporta energía al equipo.</li><li>No se basa en el talento</li></ul><h3 id="_3-inteligente-emocionalmente" tabindex="-1">3. Inteligente (emocionalmente) <a class="header-anchor" href="#_3-inteligente-emocionalmente" aria-label="Permalink to &quot;3. Inteligente (emocionalmente)&quot;">​</a></h3><ul><li>Lee bien las situaciones y las personas.</li><li>Sabe cuándo hablar y cuándo escuchar.</li><li>Gestiona sus propias emociones</li><li>Apoya a sus compañeros de equipo de manera adecuada</li><li>Maneja los conflictos de manera constructiva</li></ul><h2 id="los-fundamentos-del-exito-del-equipo" tabindex="-1">Los fundamentos del éxito del equipo <a class="header-anchor" href="#los-fundamentos-del-exito-del-equipo" aria-label="Permalink to &quot;Los fundamentos del éxito del equipo&quot;">​</a></h2><h3 id="metas-y-vision-compartidas" tabindex="-1">Metas y visión compartidas <a class="header-anchor" href="#metas-y-vision-compartidas" aria-label="Permalink to &quot;Metas y visión compartidas&quot;">​</a></h3><p>Los equipos fuertes tienen:</p><ul><li>Objetivos claros y acordados</li><li>Objetivos individuales alineados con los objetivos del equipo</li><li>Comprensión compartida de lo que significa el éxito</li><li>Compromiso con la misión colectiva</li></ul><p><strong>Preguntas para discutir con tu equipo:</strong></p><ul><li>¿Qué estamos tratando de lograr juntos?</li><li>¿Cómo se ve el éxito para nosotros?</li><li>¿Cómo nuestros objetivos individuales apoyan al equipo?</li></ul><h3 id="comunicacion-eficaz" tabindex="-1">Comunicación eficaz <a class="header-anchor" href="#comunicacion-eficaz" aria-label="Permalink to &quot;Comunicación eficaz&quot;">​</a></h3><p>La comunicación es el elemento vital del rendimiento del equipo.</p><p><strong>Buena comunicación en equipo:</strong></p><ul><li>Abierto y honesto</li><li>Respetuoso, incluso en el desacuerdo</li><li>Claro y específico</li><li>Bidireccional (hablar y escuchar)</li><li>Oportuno (información correcta en el momento correcto)</li></ul><p><strong>Durante los juegos:</strong></p><ul><li>Discuta la estrategia antes de cada final</li><li>Compartir observaciones sobre el terreno y los oponentes.</li><li>Coordinar quién lanza cuándo</li><li>Apoyémonos mutuamente después de los lanzamientos (buenos o malos)</li></ul><h3 id="confianza-y-respeto" tabindex="-1">Confianza y respeto <a class="header-anchor" href="#confianza-y-respeto" aria-label="Permalink to &quot;Confianza y respeto&quot;">​</a></h3><p>Sin confianza, los equipos se desmoronan bajo presión.</p><p><strong>Generando confianza:</strong></p><ul><li>Sé confiable (haz lo que dices)</li><li>Ser competente (hacer bien su trabajo)</li><li>Sé honesto (incluso cuando sea difícil)</li><li>Mostrar vulnerabilidad (admitir dificultades)</li><li>Apoyar a los demás de manera constante</li></ul><p><strong>Mostrando respeto:</strong></p><ul><li>Valorar la contribución de cada persona</li><li>Escucha diferentes perspectivas</li><li>Reconozca el esfuerzo, no sólo los resultados</li><li>Tratar el rol de cada uno como importante</li></ul><h3 id="roles-claros" tabindex="-1">Roles claros <a class="header-anchor" href="#roles-claros" aria-label="Permalink to &quot;Roles claros&quot;">​</a></h3><p>Todo el mundo debería entender:</p><ul><li>Sus principales responsabilidades</li><li>Cómo contribuyen al equipo</li><li>Lo que otros esperan de ellos</li><li>Cuándo dar un paso adelante y cuándo dar un paso atrás</li></ul><p><strong>En triples:</strong></p><table tabindex="0"><thead><tr><th>Role</th><th>Enfoque principal</th><th>Cualidades clave</th></tr></thead><tbody><tr><td>Puntero</td><td>Coloque las bolas cerca del jack</td><td>Precisión, consistencia</td></tr><tr><td>Medio</td><td>Adaptarse a la situación</td><td>Versatilidad, juego de lectura.</td></tr><tr><td>Tirador</td><td>Retirar las bolas del oponente</td><td>Precisión bajo presión</td></tr></tbody></table><p>Los roles pueden ser flexibles, pero la claridad ayuda.</p><h2 id="dinamica-del-equipo-durante-la-competicion" tabindex="-1">Dinámica del equipo durante la competición <a class="header-anchor" href="#dinamica-del-equipo-durante-la-competicion" aria-label="Permalink to &quot;Dinámica del equipo durante la competición&quot;">​</a></h2><h3 id="antes-del-partido" tabindex="-1">Antes del partido <a class="header-anchor" href="#antes-del-partido" aria-label="Permalink to &quot;Antes del partido&quot;">​</a></h3><ul><li>Llegar juntos, calentar juntos</li><li>Discutir la estrategia general</li><li>Establezca el tono (positivo, centrado)</li><li>Comprueba cómo se siente cada uno.</li></ul><h3 id="durante-el-juego" tabindex="-1">Durante el juego <a class="header-anchor" href="#durante-el-juego" aria-label="Permalink to &quot;Durante el juego&quot;">​</a></h3><ul><li>Comunicarse entre extremos</li><li>Manténgase positivo independientemente del resultado</li><li>Apoyarnos mutuamente después de los errores</li><li>Celebremos juntos los éxitos (brevemente)</li><li>Manténgase enfocado en el proceso, no en el resultado</li></ul><h3 id="despues-de-los-errores" tabindex="-1">Después de los errores <a class="header-anchor" href="#despues-de-los-errores" aria-label="Permalink to &quot;Después de los errores&quot;">​</a></h3><p>Qué NO hacer:</p><ul><li>Mostrar frustración visiblemente</li><li>Criticar o culpar</li><li>Retirarse o guardar silencio</li><li>Reflexiona sobre lo que pasó</li></ul><p>Qué hacer:</p><ul><li>Reconocimiento rápido (&quot;no hay problema&quot;)</li><li>Mover el foco al siguiente lanzamiento</li><li>Mantener un lenguaje corporal positivo</li><li>Confía en que tu compañero de equipo se recuperará</li></ul><h3 id="despues-del-juego" tabindex="-1">Después del juego <a class="header-anchor" href="#despues-del-juego" aria-label="Permalink to &quot;Después del juego&quot;">​</a></h3><ul><li>Informe conjunto (qué funcionó, qué no)</li><li>Reconocer las contribuciones individuales</li><li>Discutir mejoras para la próxima vez</li><li>Mantener relaciones sin importar el resultado</li></ul><h2 id="patrones-de-comunicacion" tabindex="-1">Patrones de comunicación <a class="header-anchor" href="#patrones-de-comunicacion" aria-label="Permalink to &quot;Patrones de comunicación&quot;">​</a></h2><h3 id="retroalimentacion-constructiva" tabindex="-1">Retroalimentación constructiva <a class="header-anchor" href="#retroalimentacion-constructiva" aria-label="Permalink to &quot;Retroalimentación constructiva&quot;">​</a></h3><p><strong>Pobre:</strong> &quot;Sigues fallando esos tiros&quot; <strong>Mejor:</strong> &quot;Noté que los tiros van hacia la izquierda. ¿Quieres intentar ajustar tu postura?&quot;</p><h3 id="respuesta-de-apoyo-a-los-errores" tabindex="-1">Respuesta de apoyo a los errores <a class="header-anchor" href="#respuesta-de-apoyo-a-los-errores" aria-label="Permalink to &quot;Respuesta de apoyo a los errores&quot;">​</a></h3><p><strong>Pobre:</strong> <em>Silencio o frustración visible</em><strong>Mejor:</strong> &quot;Dificil. Te toca el siguiente.&quot;</p><h3 id="discusion-estrategica" tabindex="-1">Discusión estratégica <a class="header-anchor" href="#discusion-estrategica" aria-label="Permalink to &quot;Discusión estratégica&quot;">​</a></h3><p><strong>Pobre:</strong> &quot;Sólo dispárale&quot; <strong>Mejor:</strong> &quot;¿Qué opinas: apuntar para bloquear o intentar disparar? Veo pros y contras en ambos casos&quot;.</p><h2 id="construyendo-cultura-de-equipo" tabindex="-1">Construyendo cultura de equipo <a class="header-anchor" href="#construyendo-cultura-de-equipo" aria-label="Permalink to &quot;Construyendo cultura de equipo&quot;">​</a></h2><p>Los grandes equipos desarrollan compartido:</p><ul><li><strong>Valores:</strong> Lo que representamos</li><li><strong>Normas:</strong> Cómo nos comportamos</li><li><strong>Idioma:</strong> Cómo nos comunicamos</li><li><strong>Rituales:</strong> Lo que hacemos juntos</li></ul><p><strong>Ejemplos:</strong></p><ul><li>Siempre estrechar la mano antes y después</li><li>Frases de aliento específicas</li><li>Rutina previa al juego juntos</li><li>Comida o bebida después del partido</li></ul><h2 id="en-esta-seccion" tabindex="-1">En esta sección <a class="header-anchor" href="#en-esta-seccion" aria-label="Permalink to &quot;En esta sección&quot;">​</a></h2><ul><li><strong><a href="/es/educacion/jugador-de-equipo/comunicacion">Comunicación en equipo</a></strong> - Guía detallada para comunicarse eficazmente</li></ul><h2 id="conclusion-clave" tabindex="-1">Conclusión clave <a class="header-anchor" href="#conclusion-clave" aria-label="Permalink to &quot;Conclusión clave&quot;">​</a></h2><blockquote><p>Tu equipo es tan fuerte como su relación más débil, no su jugador más débil.</p></blockquote><p>Invierte en tus compañeros. Genera confianza. Comunícate bien. Triunfen juntos.</p>',61))])}]]);export{c as __pageData,p as default};
